/* Omer games – PWA helper (same file in every app folder; generated by tools/new-game-pwa.py).
   - registers this folder's service worker (scope = this folder)
   - shows a small "📲 התקן כאפליקציה" button inside any element with [data-pwa-slot]
   - Android/Chrome: uses beforeinstallprompt; iOS Safari: shows Hebrew "Share → Add to Home Screen" steps
   - ?install=1 in the URL opens the install panel right away
   - on the menu, adds a small 📲 badge to each a.game tile (opens that game with ?install=1) */
(() => {
  if ('serviceWorker' in navigator && location.protocol !== 'file:') {
    const reg = () => navigator.serviceWorker.register('sw.js', { scope: './' }).catch(e => console.warn('sw', e));
    addEventListener('load', () => { if (navigator.onLine) reg(); else addEventListener('online', reg, { once: true }); });
  }
  const standalone = matchMedia('(display-mode: standalone)').matches || matchMedia('(display-mode: fullscreen)').matches || navigator.standalone === true;
  const ua = navigator.userAgent;
  const ios = /iphone|ipad|ipod/i.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  let deferred = null;
  document.documentElement.classList.toggle('pwa-standalone', standalone);

  const css = `
  .pwa-btn{font-family:inherit;font-size:17px;font-weight:bold;color:#3b4cca;background:rgba(255,255,255,.9);border:3px solid #3b4cca;border-radius:22px;padding:6px 14px;margin:12px auto 0;display:block;cursor:pointer;box-shadow:0 3px 0 rgba(0,0,0,.2)}
  .pwa-btn:active{transform:translateY(2px)}
  .pwa-standalone .pwa-btn,.pwa-standalone .pwa-badge,.pwa-installed .pwa-btn,.pwa-installed .pwa-badge{display:none!important}
  .pwa-badge{position:absolute;top:10px;left:10px;width:44px;height:44px;border-radius:50%;background:rgba(255,255,255,.92);border:3px solid #fff;font-size:22px;display:flex;align-items:center;justify-content:center;box-shadow:0 3px 0 rgba(0,0,0,.25);z-index:2}
  .pwa-ov{position:fixed;inset:0;z-index:99999;background:rgba(20,30,90,.6);display:flex;align-items:center;justify-content:center;direction:rtl;font-family:"Arial Rounded MT Bold","Varela Round",Arial,sans-serif}
  .pwa-panel{background:#fff;border:6px solid #ffcb05;border-radius:28px;padding:18px 20px;max-width:92vw;width:380px;text-align:center;position:relative;color:#333}
  .pwa-panel img{width:84px;height:84px;border-radius:20px;box-shadow:0 4px 10px rgba(0,0,0,.25)}
  .pwa-panel h2{margin:8px 0;color:#3b4cca;font-size:24px}
  .pwa-panel ol{text-align:right;font-size:19px;line-height:1.6;padding-inline-start:26px;margin:8px 0}
  .pwa-panel .go{font-family:inherit;font-size:24px;font-weight:bold;color:#fff;background:linear-gradient(135deg,#43a047,#00c853);border:4px solid #fff;border-radius:28px;padding:8px 26px;box-shadow:0 5px 0 #1b5e20;cursor:pointer;margin-top:8px}
  .pwa-x{position:absolute;top:8px;left:10px;font-size:22px;background:none;border:none;cursor:pointer}
  .pwa-share{display:inline-block;border:2px solid #007aff;color:#007aff;border-radius:6px;padding:0 5px;font-size:16px}`;
  const st = document.createElement('style'); st.textContent = css; document.head.appendChild(st);

  const icon = (document.querySelector('link[rel="apple-touch-icon"]') || {}).href || 'icons/icon-192.png';
  const title = document.title.replace(/[^\u0590-\u05FF'"׳״ \w-]/g, '').trim();
  function panel(html) {
    close();
    const ov = document.createElement('div'); ov.className = 'pwa-ov'; ov.id = 'pwaOv';
    ov.innerHTML = `<div class="pwa-panel"><button class="pwa-x" aria-label="סגור">✖</button><img src="${icon}" alt=""><h2>${title}</h2>${html}</div>`;
    ov.addEventListener('click', e => { if (e.target === ov || e.target.classList.contains('pwa-x')) close(); });
    document.body.appendChild(ov); return ov;
  }
  function close() { const o = document.getElementById('pwaOv'); if (o) o.remove(); }
  function iosSteps() {
    panel(`<div style="font-size:19px">להוספה למסך הבית באייפון / אייפד:</div><ol>
      <li>לוחצים על <span class="pwa-share">שתף ⬆️</span> בספארי</li>
      <li>בוחרים <b>"הוסף למסך הבית"</b> ➕</li>
      <li>לוחצים <b>"הוסף"</b> – וזהו! 🎉</li></ol>`);
  }
  function androidSteps() {
    panel(`<div style="font-size:19px">להוספה למסך הבית:</div><ol>
      <li>פותחים את תפריט הדפדפן <b>⋮</b></li>
      <li>בוחרים <b>"התקנת אפליקציה"</b> או <b>"הוספה למסך הבית"</b> ➕</li></ol>`);
  }
  async function install() {
    if (ios) return iosSteps();
    if (deferred) { const d = deferred; deferred = null; close(); d.prompt(); try { await d.userChoice; } catch (e) {} return; }
    if (ios) iosSteps(); else androidSteps();
  }
  function askPanel() { // big friendly panel (for ?install=1); the button press is the user gesture prompt() needs
    if (ios) return iosSteps();
    const ov = panel(`<div style="font-size:19px">שמים את המשחק במסך הבית ומשחקים גם בלי אינטרנט</div><button class="go">📲 התקן</button>`);
    ov.querySelector('.go').addEventListener('click', install);
  }
  addEventListener('beforeinstallprompt', e => { e.preventDefault(); deferred = e; });
  addEventListener('appinstalled', () => { deferred = null; document.documentElement.classList.add('pwa-installed'); close(); });

  function ready() {
    if (standalone) return;
    document.querySelectorAll('[data-pwa-slot]').forEach(slot => {
      if (slot.querySelector('.pwa-btn')) return;
      const b = document.createElement('button'); b.className = 'pwa-btn'; b.type = 'button'; b.textContent = '📲 התקן כאפליקציה';
      b.addEventListener('click', e => { e.stopPropagation(); install(); }); slot.appendChild(b);
    });
    document.querySelectorAll('a.game').forEach(a => {
      if (a.querySelector('.pwa-badge')) return;
      if (getComputedStyle(a).position === 'static') a.style.position = 'relative';
      const s = document.createElement('span'); s.className = 'pwa-badge'; s.textContent = '📲'; s.setAttribute('role', 'button'); s.setAttribute('aria-label', 'התקן את המשחק');
      s.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); location.href = a.getAttribute('href').replace(/index\.html$/, '') + 'index.html?install=1'; });
      a.appendChild(s);
    });
    if (/[?&]install=1/.test(location.search)) askPanel();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ready); else ready();
  window.__pwa = { install, get deferred() { return !!deferred; }, standalone, ios };
})();
